async def start_test(request:Request):
    body=await request.json();user=telegram_user_from_request(request,body)
    if not user:return {"ok":False,"error":"Telegram userni tasdiqlab bo'lmadi."}
    typ=body.get("testType","iq")
    if typ not in QUESTION_SETS:return {"ok":False,"error":"Test turi noto'g'ri."}
    tid=await upsert_user(user)
    async with db_pool.acquire() as c:row=await c.fetchrow("SELECT recent_questions FROM users WHERE telegram_id=$1",tid)
    recent=row["recent_questions"] if row and isinstance(row["recent_questions"],dict) else {}
    used=set(recent.get(typ,[]))
    pool=QUESTION_BANKS[typ];available=[x for i,x in enumerate(pool,1) if f"{typ}_{i}" not in used]
    if len(available)<10:used=set();available=pool
    selected=random.sample(available,10);qids=[f"{typ}_{pool.index(x)+1}" for x in selected]
    return {"ok":True,"testToken":create_test_token(tid,typ,qids),"testType":typ,"testName":QUESTION_SETS[typ],"questions":[{"id":q,"q":QUESTION_BY_ID[q]["q"],"a":QUESTION_BY_ID[q]["a"]} for q in qids]}

@app.post("/api/test/submit")
async def submit_test(request:Request):
    body=await request.json();user=telegram_user_from_request(request,body)
    if not user:return {"ok":False,"error":"Telegram userni tasdiqlab bo'lmadi."}
    tid=int(user["id"]);tok=verify_test_token(body.get("testToken",""),tid)
    if not tok:return {"ok":False,"error":"Test sessiyasi yaroqsiz yoki muddati o'tgan."}
    answers=body.get("answers")
    typ=tok["type"]
    if not isinstance(answers,list) or len(answers)!=10:return {"ok":False,"error":"Test to'liq yakunlanmagan."}
    expected=tok["q"];received=[];correct=0;total=0.0
    for pos,item in enumerate(answers):
        if not isinstance(item,dict):return {"ok":False,"error":"Javob formati noto'g'ri."}
        try:qid=str(item["questionId"]);ai=int(item["answerIndex"]);ts=float(item["timeSeconds"])
        except (KeyError,TypeError,ValueError):return {"ok":False,"error":"Javob ma'lumotlari noto'g'ri."}
        if qid!=expected[pos] or qid in received:return {"ok":False,"error":"Test javoblari noto'g'ri yoki takrorlangan."}
        limit=TIME_LIMITS[typ]
        if not -1<=ai<4 or not 0<=ts<=limit+30:return {"ok":False,"error":"Javob vaqti noto'g'ri."}
        received.append(qid);total+=min(limit,max(0,ts))
        if ai==QUESTION_BY_ID[qid]["correct"]:correct+=1
    if typ=="speed":
        avg_time=total/10
        speed_bonus=max(0,min(30,(1-(avg_time/TIME_LIMITS[typ]))*30))
        score=round(max(0,min(100,correct*7+speed_bonus)))
    else:
        score=correct*10
    coins_earned=10+correct*2+(10 if score>=90 else 0)
    async with db_pool.acquire() as c:
        async with c.transaction():
            row=await c.fetchrow("SELECT global_score,best_score,tests_taken,recent_questions FROM users WHERE telegram_id=$1 FOR UPDATE",tid)
            if not row:return {"ok":False,"error":"Foydalanuvchi topilmadi."}
            recent=row["recent_questions"] if isinstance(row["recent_questions"],dict) else {}
            recent=dict(recent);arr=list(recent.get(typ,[]));arr.extend(expected);recent[typ]=arr[-100:]
            global_score=int(row["global_score"])+score;best_score=max(int(row["best_score"]),score);tests=int(row["tests_taken"])+1
            await c.execute("INSERT INTO test_results(telegram_id,test_type,score,correct_answers,total_questions,total_time_seconds,coins_earned) VALUES($1,$2,$3,$4,10,$5,$6)",tid,typ,score,correct,round(total,2),coins_earned)
            await c.execute("UPDATE users SET global_score=$2,best_score=$3,coins=coins+$4,tests_taken=$5,recent_questions=$6::jsonb,updated_at=NOW() WHERE telegram_id=$1",tid,global_score,best_score,coins_earned,tests,json.dumps(recent,separators=(",",":")))
    return {"ok":True,"score":score,"correctAnswers":correct,"totalQuestions":10,"testType":typ,"coinsEarned":coins_earned,"globalScore":global_score}

@app.post("/api/reward/daily")
async def daily_reward(request:Request):
    body=await request.json();user=telegram_user_from_request(request,body)
    if not user:return {"ok":False,"error":"Telegram userni tasdiqlab bo'lmadi."}
    tid=int(user["id"]);today=datetime.now(timezone.utc).date()
    async with db_pool.acquire() as c:
        async with c.transaction():
            row=await c.fetchrow("SELECT last_daily_reward,streak FROM users WHERE telegram_id=$1 FOR UPDATE",tid)
            if not row:return {"ok":False,"error":"Foydalanuvchi topilmadi."}
            if row["last_daily_reward"]==today:return {"ok":False,"error":"Bugungi coin allaqachon olingan."}
            yesterday=today.fromordinal(today.toordinal()-1);streak=int(row["streak"])+1 if row["last_daily_reward"]==yesterday else 1;reward=min(25,10+(streak-1)*2)
            await c.execute("UPDATE users SET coins=coins+$2,streak=$3,last_daily_reward=$4,updated_at=NOW() WHERE telegram_id=$1",tid,reward,streak,today)
    return {"ok":True,"coins":reward,"streak":streak}

@app.get("/api/me")
async def get_me(request:Request):
    user=telegram_user_from_request(request)
    if not user:return {"ok":False,"error":"Telegram userni tasdiqlab bo'lmadi."}
    tid=await upsert_user(user)
    async with db_pool.acquire() as c:
        row=await c.fetchrow("SELECT telegram_id,username,first_name,best_score,global_score,coins,tests_taken,streak FROM users WHERE telegram_id=$1",tid)
        rows=await c.fetch("SELECT test_type,ROUND(AVG(score)) AS avg_score FROM test_results WHERE telegram_id=$1 GROUP BY test_type",tid)
    category={k:None for k in QUESTION_SETS}
    for r in rows: category[r["test_type"]]=int(r["avg_score"])
    vals=[v for v in category.values() if v is not None]
    overall=round(sum(vals)/len(vals)) if vals else 0
    return {"ok":True,"user":{"id":row["telegram_id"] if row else tid,"username":row["username"] if row else user.get("username"),"first_name":row["first_name"] if row else user.get("first_name","")},"best_score":row["best_score"] if row else 0,"global_score":row["global_score"] if row else 0,"coins":row["coins"] if row else 0,"tests_taken":row["tests_taken"] if row else 0,"streak":row["streak"] if row else 0,"level":level_for(int(row["global_score"]) if row else 0),"category_scores":category,"overall_percent":overall}

@app.get("/api/ranking")
async def ranking():
    async with db_pool.acquire() as c:rows=await c.fetch("SELECT username,first_name,global_score,tests_taken FROM users WHERE tests_taken>0 ORDER BY global_score DESC,tests_taken ASC,updated_at ASC LIMIT 100")
    return {"ok":True,"users":[{"username":r["username"],"first_name":r["first_name"],"global_score":r["global_score"],"tests_taken":r["tests_taken"]} for r in rows]}

@asynccontextmanager
async def lifespan(app_instance:FastAPI):
    await init_db();await bot.set_webhook(url=WEBHOOK_URL,drop_pending_updates=True)
    try:yield
    finally:
        try:await bot.delete_webhook()
        finally:await bot.session.close();await close_db()
app.router.lifespan_context=lifespan

